{"solution_py":""""Resolve the CLI color mode during a flag migration."""
from __future__ import annotations

from collections.abc import Sequence


def parse_color_mode(argv: Sequence[str]) -> str:
    """Return the requested color mode, defaulting to ``auto``."""
    mode = "auto"

    def set_mode(value: str) -> None:
        nonlocal mode
        if value not in {"auto", "always", "never"}:
            raise ValueError(f"invalid color mode: {value}")
        if mode != "auto" and mode != value:
            raise ValueError("conflicting color options")
        mode = value

    index = 0
    while index < len(argv):
        argument = argv[index]
        if argument == "--no-color":
            set_mode("never")
        elif argument == "--color":
            index += 1
            if index >= len(argv):
                raise ValueError("--color requires a mode")
            set_mode(argv[index])
        elif argument.startswith("--color="):
            set_mode(argument[len("--color=") :])
        index += 1

    return mode
